import{_ as t,o,c as a,ap as s,bp as i,bq as r,br as c,bs as d,bt as n,bu as l,bv as p,bw as v,bx as h}from"./chunks/framework.BumGKp4W.js";const k=JSON.parse('{"title":"Discovery","description":"","frontmatter":{"permalink":"/docs/usage/resource-management/discovery"},"headers":[],"relativePath":"docs/usage/resource-management/discovery.md","filePath":"docs/usage/resource-management/discovery.md"}'),u={name:"docs/usage/resource-management/discovery.md"};function m(b,e,y,g,f,_){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="discovery" tabindex="-1">Discovery <a class="header-anchor" href="#discovery" aria-label="Permalink to “Discovery”">​</a></h1><p>Discovery is a feature of the SLM that allows you to discover resources in your environment and provide information about them to the SLM.</p><h2 id="drivers" tabindex="-1">Drivers <a class="header-anchor" href="#drivers" aria-label="Permalink to “Drivers”">​</a></h2><p>In order to use the discovery features of the SLM, you need to have a discovery driver installed first. The driver is responsible for discovering resources in your environment and providing information about them to the SLM.</p><p>To check if you have a discovery driver installed</p><div class="info custom-block"><p class="custom-block-title">GO TO</p><p>Discovery &gt; Drivers</p></div><p>If you see a message saying &quot;No drivers available&quot;, you need to install one first. Here is one example of a discovery driver:</p><p><img src="'+i+'" alt="Overview of Discovery Drivers" data-zoomable="true"></p><h2 id="start-discovery" tabindex="-1">Start Discovery <a class="header-anchor" href="#start-discovery" aria-label="Permalink to “Start Discovery”">​</a></h2><p>To start a discovery</p><div class="info custom-block"><p class="custom-block-title">GO TO</p><p>Discovery &gt; Inbox</p></div><p>... and click on the &quot;magnifying glass&quot; button in the lower right corner: <img src="'+r+'" alt="Start Discovery" data-zoomable="true"></p><p>Then select the discovery driver you want to use and click on &quot;Scan&quot; at the bottom right of the dialog:</p><p><img src="'+c+'" alt="Start Discovery Dialog" data-zoomable="true"></p><p>At the bottom right of the window a status messages indicates that the discovery has started running:</p><p><img src="'+d+'" alt="Discovery Running" data-zoomable="true"></p><p>To check the status of the discovery job</p><div class="info custom-block"><p class="custom-block-title">GO TO</p><p>Discovery &gt; Jobs</p></div><p>The job view displays a table showing all discovery jobs and their properties:</p><p><img src="'+n+'" alt="Discovery Jobs" data-zoomable="true"></p><p>After the discovery job has finished, you can check the results in the inbox:</p><p><img src="'+l+'" alt="Discovery Results" data-zoomable="true"></p><p>To hide a discovered device in the inbox, click on the &quot;Hide&quot; button in the &quot;Actions&quot; column of the far right of the table. To add the device to the resources managed by the SLM, check the checkbox of the device and click the &quot;Add&quot; button next to the &quot;Discover&quot; button at the bottom right of the view:</p><p><img src="'+p+'" alt="Add Discovered Device" data-zoomable="true"></p><p>Confirm the adding of the device in the dialog by clicking on &quot;Add&quot; at the bottom right of the dialog:</p><p><img src="'+v+'" alt="Add Discovered Device Dialog" data-zoomable="true"></p><p>After the device has been added, the device will disappear from the discovery inbox. To see the device</p><div class="info custom-block"><p class="custom-block-title">GO TO</p><p>Devices &gt; Instances</p></div><p>where the device is listed as a resource and can be managed like any other resource:</p><p><img src="'+h+'" alt="Added Device in Resource Overview" data-zoomable="true"></p>',30)])])}const T=t(u,[["render",m]]);export{k as __pageData,T as default};
